package org.basaltmc.auth

import kotlin.test.Test
import kotlin.test.assertEquals

private fun hexToBytes(hex: String): ByteArray =
    ByteArray(hex.length / 2) { i -> hex.substring(i * 2, i * 2 + 2).toInt(16).toByte() }

/**
 * Golden vectors generated by running the real `java.math.BigInteger(digest).toString(16)` on a
 * JDK, for SHA-1 digests of known inputs. Covers a positive digest with no adjustment, a positive
 * digest with a leading zero nibble, a positive digest with a leading zero byte, and several
 * negative (two's-complement) digests.
 */
class SessionHashTest {
    @Test
    fun matchesJdkBigIntegerToHexString() {
        // "Notch": leading byte 0x4e, positive, no leading zero to strip.
        assertEquals(
            "4ed1f46bbe04bc756bcb17c0c7ce3e4632f06a48",
            SessionHash.format(hexToBytes("4ed1f46bbe04bc756bcb17c0c7ce3e4632f06a48")),
        )
        // "jeb_": leading byte 0x83, negative, needs two's-complement negation.
        assertEquals(
            "-7c9d5b0044c130109a5d7b5fb5c317c02b4e28c1",
            SessionHash.format(hexToBytes("8362a4ffbb3ecfef65a284a04a3ce83fd4b1d73f")),
        )
        // "simon": leading byte 0x08, positive, leading zero nibble stripped from the first byte.
        assertEquals(
            "88e16a1019277b15d58faf0541e11910eb756f6",
            SessionHash.format(hexToBytes("088e16a1019277b15d58faf0541e11910eb756f6")),
        )
        // "" (empty serverId): negative.
        assertEquals(
            "-25c65c11a194b4f2cdaa40106a9fe76f5027f8f7",
            SessionHash.format(hexToBytes("da39a3ee5e6b4b0d3255bfef95601890afd80709")),
        )
        // multi-part input (serverId + secret + publicKey), like the real usage: negative.
        assertEquals(
            "-7fc249fa02def4925027b6d62186cf0ede08cbc8",
            SessionHash.format(hexToBytes("803db605fd210b6dafd84929de7930f121f73438")),
        )
    }

    @Test
    fun stripsALeadingZeroNibbleFromAPositiveDigest() {
        assertEquals(
            "c92ad5a579c2fdc6ef6405b5d62641cde4c9c7e",
            SessionHash.format(hexToBytes("0c92ad5a579c2fdc6ef6405b5d62641cde4c9c7e")),
        )
    }

    @Test
    fun stripsALeadingZeroByteFromAPositiveDigest() {
        assertEquals(
            "4cbd10596a5b45194927f447e552d8e8f852be",
            SessionHash.format(hexToBytes("004cbd10596a5b45194927f447e552d8e8f852be")),
        )
    }
}
